def family_init(ctx):
    v = [float(b.get("v") or 0.0) for b in ctx.bars]
    n = len(v)
    p = max(2, int(ctx.p.vol_n))
    out = [None] * n
    run = 0.0
    for i in range(n):
        run += v[i]
        if i >= p:
            run -= v[i - p]
        if i >= p - 1:
            out[i] = run / p
    ctx.vsma = ctx.series(out, "vol_sma")


def signal(ctx, i):
    lb = max(1, int(ctx.p.lookback))
    if i < lb + 2:
        return 0
    a = ctx.a[i]
    vs = ctx.vsma[i - 1]
    if a is None or a <= 0 or vs is None or vs <= 0:
        return 0
    # (1) the prior advance, measured to the PREVIOUS close, not this one
    if ctx.c[i - 1] - ctx.c[i - 1 - lb] < float(ctx.p.adv_atr) * a:
        return 0
    # (2) volume expansion against the average as of yesterday
    if ctx.v[i] <= float(ctx.p.vol_mult) * vs:
        return 0
    # (3) a new high, (4) reversed below the open
    if ctx.h[i] <= ctx.h[i - 1] or ctx.c[i] >= ctx.o[i]:
        return 0
    rng = ctx.h[i] - ctx.l[i]
    if rng <= 0:
        return 0
    # (5) and closed in the bottom of its own range
    if (ctx.c[i] - ctx.l[i]) / rng >= float(ctx.p.clv_max):
        return 0
    return -1
